def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split pre-release (everything after '-')
        if '-' in v_no_build:
            version_part, prerelease_part = v_no_build.split('-', 1)
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_ids = prerelease_part.split('.')
            # Convert to sortable tuples
            prerelease_tuples = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_tuples.append((0, int(identifier)))
                else:
                    prerelease_tuples.append((1, identifier))
            prerelease_key = (0, tuple(prerelease_tuples))
        else:
            prerelease_key = (1,)  # No pre-release sorts after pre-release

        return (major, minor, patch, prerelease_key)

    # Create list of (sort_key, original_index, version_string)
    indexed = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    # Sort by the key, then by original index for stability
    indexed.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted version strings
    return [v for _, _, v in indexed]

